/**
 * @fileoverview Clean contract suite for `scripts/clean.sh`, the standalone cleaner of every
 * artifact generated by `scripts/build.sh`.
 *
 * @brief Verifies the tracked cleaner against its SRS contract: standalone root-resolved
 * operation (PKG-094, PKG-095), removal of exactly the PKG-072 generated `dist/` regular files
 * with preservation of non-generated entries and symlinks (PKG-096), deepest-first pruning of
 * emptied ancestor directories including `dist/` itself (PKG-097), exit-code and diagnostic
 * semantics including the absent-`dist/` no-op (PKG-098, PKG-101), and the absence of install,
 * publish, and destructive-git commands (PKG-099, PKG-100).
 * @details UUT: the tracked shell script `scripts/clean.sh`, executed from a temp-directory
 * sandbox shaped like the repository root (`scripts/clean.sh` copy plus a seeded `dist/` tree);
 * the script resolves its root from its own location, so the sandbox root is the cleaned tree.
 * Level 0 cases are static assertions over the tracked script source (no process spawn). Level 1
 * cases spawn `bash` children against the sandbox. Isolation: no network, no dependency
 * installation, no git invocation, no write into the repository tree; each sandbox is removed in
 * `finally`. No toolchain stubs are required because the cleaner has no toolchain dependency.
 * @note HDT levels: 0 (atomic static source assertions) and 1 (composed sandbox runs depending on
 * the shell runtime as the isolated external boundary). Test cases are independent and each owns
 * its sandbox.
 * @satisfies TST-030, PKG-094, PKG-095, PKG-096, PKG-097, PKG-098, PKG-099, PKG-100, PKG-101
 */
import test from "node:test";
import assert from "node:assert/strict";
import { spawnSync, type SpawnSyncReturns } from "node:child_process";
import {
  chmodSync,
  copyFileSync,
  existsSync,
  lstatSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readlinkSync,
  rmSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

/** Repository root resolved from this suite location (cwd-independent). */
const PROJECT_ROOT: string = join(dirname(fileURLToPath(import.meta.url)), "..");

/** Tracked cleaner script under test. */
const CLEAN_SCRIPT: string = join(PROJECT_ROOT, "scripts", "clean.sh");

/** Upper bound in milliseconds for one sandboxed clean run. */
const CLEAN_TIMEOUT_MS = 60000;

/** PKG-072 generated-artifact patterns the cleaner MUST apply to `dist/` regular files. */
const GENERATED_PATTERNS = ["*.js", "*.js.map", "*.d.ts", "*.d.ts.map", "*.tgz", "*.tsbuildinfo", "*.tmp"];

/**
 * @brief Reads the tracked cleaner source once per static assertion.
 * @details The tracked script is an immutable input during the test run, so caching is
 * unnecessary; a missing file fails the test through the thrown error. Complexity O(file size).
 * @return {string} Raw UTF-8 source of `scripts/clean.sh`.
 * @throws {Error} When the script does not exist or cannot be read.
 */
function readCleanScript(): string {
  return readFileSync(CLEAN_SCRIPT, "utf-8");
}

/**
 * @brief Creates an isolated sandbox shaped like the repository root for one clean run.
 * @details Creates a temp directory under the OS temp root containing only `scripts/clean.sh`
 * copied from the tracked source; the cleaner resolves this root from its own location
 * (PKG-095). Complexity O(1) filesystem operations.
 * @return {string} Sandbox root; the caller MUST remove it in a `finally` block.
 * @throws {Error} When the sandbox directories or the script copy cannot be created.
 * @side_effect Creates one directory tree under the OS temp root.
 */
function createSandbox(): string {
  const root = mkdtempSync(join(tmpdir(), "clean-script-contract-"));
  mkdirSync(join(root, "scripts"));
  copyFileSync(CLEAN_SCRIPT, join(root, "scripts", "clean.sh"));
  chmodSync(join(root, "scripts", "clean.sh"), 0o755);
  return root;
}

/**
 * @brief Seeds one file inside the sandbox `dist/` tree with parent directories.
 * @details Complexity O(n) in content length.
 * @param root {string} Sandbox root.
 * @param relative {string} Path relative to `dist/`, POSIX separators.
 * @param content {string} File content.
 * @return {string} Absolute path of the seeded file.
 * @throws {Error} When directory creation or the write fails.
 * @side_effect Creates directories and one file under `<root>/dist`.
 */
function seedDistFile(root: string, relative: string, content: string): string {
  const absolute = join(root, "dist", ...relative.split("/"));
  mkdirSync(dirname(absolute), { recursive: true });
  writeFileSync(absolute, content);
  return absolute;
}

/**
 * @brief Runs the sandboxed copy of `scripts/clean.sh` as a bash child process.
 * @details Executes by absolute path; `cwd` defaults to the sandbox root and MAY be any foreign
 * directory to prove cwd independence (PKG-095). Output is captured as UTF-8 text; the child is
 * bounded by `CLEAN_TIMEOUT_MS`. Complexity O(output size) plus one child process.
 * @param root {string} Sandbox root produced by `createSandbox`.
 * @param cwd {string | undefined} Child working directory; defaults to the sandbox root.
 * @return {SpawnSyncReturns<string>} Child exit status and captured stdout/stderr.
 * @throws {Error} When bash cannot be spawned.
 */
function runClean(root: string, cwd?: string): SpawnSyncReturns<string> {
  return spawnSync("bash", [join(root, "scripts", "clean.sh")], {
    cwd: cwd ?? root,
    encoding: "utf8",
    timeout: CLEAN_TIMEOUT_MS,
  });
}

test("test_clean_script_declares_the_standalone_root_resolved_contract", () => {
  // PKG-094/PKG-095/PKG-096/PKG-101: the tracked script MUST exist as an executable-shaped bash
  // cleaner resolving the repository root from its own location, MUST classify generated files
  // with the exact PKG-072 pattern set, and MUST report removed paths plus a PASS/FAILED result.
  // Arrange
  const source = readCleanScript();
  // Act
  const hasShebang = source.startsWith("#!/usr/bin/env bash");
  const hasStrictMode = source.includes("set -euo pipefail");
  const hasRootResolution = source.includes('cd "$(dirname "$0")/.."');
  const scopedDist = source.includes('readonly DIST_DIR="dist"');
  const classifierPatterns = GENERATED_PATTERNS.every((pattern) => source.includes(pattern));
  const reportsPass = source.includes("PASS");
  const reportsFailure = source.includes("FAILED");
  // Assert
  const expected_output = true;
  assert.equal(hasShebang, expected_output, "clean.sh MUST carry the bash shebang (PKG-094)");
  assert.equal(hasStrictMode, expected_output, "clean.sh MUST enable strict mode (PKG-098)");
  assert.equal(hasRootResolution, expected_output, "clean.sh MUST resolve the repository root from its own location (PKG-095)");
  assert.equal(scopedDist, expected_output, "clean.sh MUST scope removal to the dist/ directory (PKG-096)");
  assert.equal(classifierPatterns, expected_output, "clean.sh MUST apply the exact PKG-072 generated-pattern set (PKG-096)");
  assert.equal(reportsPass, expected_output, "clean.sh MUST print a final PASS result line (PKG-101)");
  assert.equal(reportsFailure, expected_output, "clean.sh MUST print FAILED diagnostics (PKG-101)");
});

test("test_clean_script_never_installs_publishes_or_invokes_destructive_git", () => {
  // PKG-099/PKG-100: the cleaner MUST NOT install dependencies, publish packages, or invoke
  // destructive git commands; this is a negative static contract over the tracked source.
  // Arrange
  const source = readCleanScript();
  // Act
  const installsOrPublishes = /\bnpm\s+(ci|install|publish)\b/.test(source);
  const destructiveGit = /\bgit\s+(clean|reset|stash|checkout|restore)\b/.test(source);
  // Assert
  const expected_output = false;
  assert.equal(installsOrPublishes, expected_output, "clean.sh MUST NOT install or publish (PKG-099)");
  assert.equal(destructiveGit, expected_output, "clean.sh MUST NOT invoke destructive git commands (PKG-100)");
});

test("test_clean_removes_every_generated_artifact_and_prunes_the_fully_generated_tree", () => {
  // PKG-094/PKG-096/PKG-097/PKG-098/PKG-101: a dist/ tree holding only generated artifacts MUST
  // be removed entirely, including emptied nested directories and dist/ itself; the stdout report
  // MUST name each removed path and end with PASS.
  // Arrange
  const root = createSandbox();
  try {
    const generated = [
      "cli.js",
      "index.js",
      "chunk-ABC.js",
      "cli.d.ts",
      "index.d.ts",
      "fixture-pkg-1.0.0.tgz",
      "trace.tsbuildinfo",
      "note.tmp",
      "sub/nested.js.map",
      "sub/deep/module.d.ts.map",
    ];
    for (const relative of generated) {
      seedDistFile(root, relative, "generated\n");
    }
    // Act
    const result = runClean(root);
    // Assert
    assert.equal(result.status, 0, `clean MUST exit 0; stderr: ${result.stderr}`);
    for (const relative of generated) {
      assert.equal(existsSync(join(root, "dist", ...relative.split("/"))), false, `generated artifact must be removed: ${relative}`);
    }
    assert.equal(existsSync(join(root, "dist")), false, "fully generated dist/ MUST be pruned (PKG-097)");
    assert.equal(result.stdout.includes("removed: dist/cli.js"), true, "stdout MUST name each removed path (PKG-101)");
    assert.equal(/PASS: removed 10 generated artifact/.test(result.stdout), true, "stdout MUST end with the PASS result line (PKG-101)");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("test_clean_preserves_non_generated_entries_symlinks_and_preexisting_empty_directories", () => {
  // PKG-096/PKG-097: non-generated regular files, symlinks named like generated outputs, and
  // pre-existing empty directories MUST survive; only generated regular files are removed and a
  // directory holding any surviving entry MUST NOT be pruned.
  // Arrange
  const root = createSandbox();
  try {
    seedDistFile(root, "cli.js", "generated\n");
    seedDistFile(root, "sub/nested.d.ts", "generated\n");
    seedDistFile(root, "README.md", "user note\n");
    seedDistFile(root, "sub/keep.txt", "user data\n");
    const linkTarget = seedDistFile(root, "symlink-target.txt", "target\n");
    const linkPath = join(root, "dist", "fake.js");
    symlinkSync(linkTarget, linkPath);
    const emptyDirectory = join(root, "dist", "preserve-empty");
    mkdirSync(emptyDirectory);
    // Act
    const result = runClean(root);
    // Assert
    assert.equal(result.status, 0, `clean MUST exit 0; stderr: ${result.stderr}`);
    assert.equal(existsSync(join(root, "dist", "cli.js")), false, "generated cli.js must be removed");
    assert.equal(existsSync(join(root, "dist", "sub", "nested.d.ts")), false, "generated nested.d.ts must be removed");
    assert.equal(existsSync(join(root, "dist", "README.md")), true, "non-generated README.md MUST be preserved (PKG-096)");
    assert.equal(existsSync(linkPath), true, "symlink named like a generated file MUST be preserved (PKG-096)");
    assert.equal(lstatSync(linkPath).isSymbolicLink(), true, "preserved entry MUST stay a symlink");
    assert.equal(readlinkSync(linkPath), linkTarget, "symlink target MUST be unchanged");
    assert.equal(existsSync(emptyDirectory), true, "pre-existing empty directory MUST be preserved (PKG-096)");
    assert.equal(existsSync(join(root, "dist", "sub")), true, "directory holding a non-generated entry MUST NOT be pruned (PKG-097)");
    assert.equal(existsSync(join(root, "dist")), true, "dist/ holding non-generated entries MUST NOT be pruned (PKG-097)");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("test_clean_succeeds_as_noop_when_dist_is_absent", () => {
  // PKG-098/PKG-101: an absent dist/ is a successful no-op ending with the PASS result line,
  // and no dist/ directory is created.
  // Arrange
  const root = createSandbox();
  try {
    // Act
    const result = runClean(root);
    // Assert
    const expected_output = { exitCode: 0, distCreated: false };
    assert.equal(result.status, expected_output.exitCode, `absent dist/ MUST exit 0; stderr: ${result.stderr}`);
    assert.equal(/PASS: removed 0 generated artifact/.test(result.stdout), true, "stdout MUST carry the PASS result line (PKG-101)");
    assert.equal(existsSync(join(root, "dist")), expected_output.distCreated, "no-op clean MUST NOT create dist/ (PKG-096)");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("test_clean_fails_when_dist_is_not_a_directory", () => {
  // PKG-098/PKG-101: a non-directory dist entry MUST abort with exit 1 and a stderr FAILED
  // diagnostic naming the entry; the entry itself MUST NOT be removed.
  // Arrange
  const root = createSandbox();
  try {
    const distFile = join(root, "dist");
    writeFileSync(distFile, "not a directory\n");
    // Act
    const result = runClean(root);
    // Assert
    assert.equal(result.status, 1, "non-directory dist MUST exit 1 (PKG-098)");
    assert.equal(result.stderr.includes("FAILED"), true, "stderr MUST carry the FAILED diagnostic (PKG-101)");
    assert.equal(result.stderr.includes("dist"), true, "diagnostic MUST name the failed entry (PKG-101)");
    assert.equal(existsSync(distFile), true, "the non-directory entry MUST NOT be removed (PKG-096)");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("test_clean_produces_identical_results_from_a_foreign_working_directory", () => {
  // PKG-095: invoking the script by absolute path from a foreign cwd MUST clean the sandbox tree
  // resolved from the script location, never the caller's cwd.
  // Arrange
  const root = createSandbox();
  try {
    seedDistFile(root, "cli.js", "generated\n");
    seedDistFile(root, "README.md", "user note\n");
    // Act
    const result = runClean(root, tmpdir());
    // Assert
    assert.equal(result.status, 0, `foreign-cwd clean MUST exit 0; stderr: ${result.stderr}`);
    assert.equal(existsSync(join(root, "dist", "cli.js")), false, "generated artifact MUST be removed from the script-rooted tree (PKG-095)");
    assert.equal(existsSync(join(root, "dist", "README.md")), true, "non-generated entry MUST survive the foreign-cwd run (PKG-096)");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("test_clean_is_idempotent_across_repeated_runs", () => {
  // PKG-098: a second clean over an already-cleaned tree MUST exit 0 again and report zero
  // removals, without touching non-generated survivors.
  // Arrange
  const root = createSandbox();
  try {
    seedDistFile(root, "cli.js", "generated\n");
    seedDistFile(root, "README.md", "user note\n");
    // Act
    const first = runClean(root);
    const second = runClean(root);
    // Assert
    assert.equal(first.status, 0, `first clean MUST exit 0; stderr: ${first.stderr}`);
    assert.equal(second.status, 0, `second clean MUST exit 0; stderr: ${second.stderr}`);
    assert.equal(/PASS: removed 0 generated artifact/.test(second.stdout), true, "second run MUST report zero removals (PKG-098)");
    assert.equal(existsSync(join(root, "dist", "README.md")), true, "non-generated entry MUST survive both runs (PKG-096)");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
